before.content:
        List<JsonNode> values = harness.requestCollecting(4, "session/prompt", Map.of("sessionId", sessionId,
                "prompt", List.of(Map.of("type", "text", "text", "write"))));
        values.addAll(harness.updatesUntilIdle());
        assertTrue(values.stream().anyMatch(message -> "diff".equals(message.path("params").path("update")
                .path("content").path(0).path("type").asText())));
    }
}

after.content:
        List<JsonNode> values = harness.requestCollecting(4, "session/prompt", Map.of("sessionId", sessionId,
                "prompt", List.of(Map.of("type", "text", "text", "write"))));
        values.addAll(harness.updatesUntilIdle());
        int diffIndex = java.util.stream.IntStream.range(0, values.size())
                .filter(index -> "diff".equals(values.get(index).path("params").path("update")
                        .path("content").path(0).path("type").asText()))
                .findFirst().orElse(-1);
        int idleIndex = java.util.stream.IntStream.range(0, values.size())
                .filter(index -> "idle".equals(values.get(index).path("params").path("update")
                        .path("state").asText()))
                .findFirst().orElse(-1);
        assertTrue(diffIndex >= 0 && diffIndex < idleIndex);
    }
}
